ewcommand{\sv}{x_m}
ewcommand{\uv}{u_m}
ewcommand{\Am}{A_m}
ewcommand{\Bm}{B_m}
Let $x_m\in\mathbb R^n$, $u_m\in\mathbb R^m$, $A_m\in\mathbb R^{n	imes n}$, and $B_m\in\mathbb R^{n	imes m}$.
\[\dot{\sv}=\Am\sv+\Bm\uv\]

\newcommand{\SysA}{F_m}\newcommand{\SysB}{G_m}
The vectors $z_m\in\mathbb R^p$ and $v_m\in\mathbb R^r$ and matrices $F_m\in\mathbb R^{p\times p}$ and $G_m\in\mathbb R^{p\times r}$ define a state-space model.
\[\dot{z_m}=\SysA z_m+\SysB v_m\]

\newcommand{\dyn}[1]{\operatorname{mystery}(#1)}
Let $x_{49}\in\mathbb R^n$, $u_{49}\in\mathbb R^m$, $A_{49}\in\mathbb R^{n\times n}$, and $B_{49}\in\mathbb R^{n\times m}$.
\[\dyn{x_{49}}=A_{49}x_{49}+B_{49}u_{49}\]

ewcommand{\Aa}{A_m}
ewcommand{\Pp}{P_m}
ewcommand{\Qq}{Q_m}
Let $A_m,P_m,Q_m\in\mathbb R^{n	imes n}$.
\[\Aa^	op\Pp+\Pp\Aa=-\Qq\]

\newcommand{\tr}{^{\mathsf T}}
Let $F_m,X_m,R_m\in\mathbb R^{p\times p}$.
\[F_m\tr X_m+X_mF_m=-R_m\]

\newcommand{\adjoint}{\operatorname{adj}}
Let $A_{49},P_{49},Q_{49}\in\mathbb R^{n\times n}$.
\[\adjoint(A_{49})P_{49}+P_{49}A_{49}=-Q_{49}\]
